      "name": "vol_reversal_depth",
      "expression": "TS_ARGMAX(TS_ZSCORE(RANK($volume), 20), 5) - TS_ARGMIN(TS_ZSCORE(RANK($return), 20), 5)",
      "explanation": "Explores depth by finding the maximum and minimum ranks of volume and return, normalized by z-score, across different windows."
    },
    {
      "name": "vol_return_corr",
      "expression": "TS_CORR($close, $volume, 10) * RANK($return, 30)",
      "explanation": "Unusual pairing of close price with volume and return rank, capturing correlation and ranking effects."
    },
    {
      "name": "vol_timescale_ratio",
      "expression": "TS_RSI($volume, 5) / TS_RSI($volume, 20)",
      "explanation": "Timescale contrast using RSI on volume at fast and slow windows to detect momentum shifts."
    },
    {
      "name": "vol_normalised_rank",
      "expression": "RANK($return) / TS_MAD($volume, 15)",
      "explanation": "Odd normalisation by dividing return rank by volume MAD to adjust for volatility."
    },
    {
      "name": "vol_order_stat",
      "expression": "TS_ARGMAX($volume, 10) WHERE $return < MEDIAN($return, 10)",
      "explanation": "Order statistics focusing on volume maxima where returns are below median, highlighting extreme events."
    },
    {
      "name": "vol_shape_diff",
      "expression": "TS_SKEW($return, 25) - TS_KURT($volume, 25)",
      "explanation": "Shape analysis comparing return skewness and volume kurtosis to capture distributional differences."
    }
  ]
}

